/// Tail-bound replay witness. It is intentionally neither cloneable nor
/// serializable and has no public constructor.
static NEXT_V4_SESSION_IDENTITY: AtomicU64 = AtomicU64::new(1);

/// Process-local, one-owner identity used to prevent a prepared v4 value from
/// crossing between independently locked replay sessions that happen to name
/// the same durable prefix.
///
/// ```compile_fail
/// fn require_clone<T: Clone>() {}
/// require_clone::<reviewgraphen_core::OpaqueSessionIdentityV4>();
/// ```
///
/// ```compile_fail
/// fn require_serialize<T: serde::Serialize>() {}
/// require_serialize::<reviewgraphen_core::OpaqueSessionIdentityV4>();
/// ```
#[derive(Debug)]
pub struct OpaqueSessionIdentityV4 {
    digest: ContentHash,
    replay_binding: RefCell<Option<SessionReplayBindingV4>>,
}

#[derive(Debug)]
struct SessionReplayBindingV4 {
    run_id: StableId,
    genesis_hash: ContentHash,
    confirmed_tail_hash: ContentHash,
}

impl OpaqueSessionIdentityV4 {
    /// Creates a fresh process-local identity. It grants no durable or review
    /// authority and is useful only while held by one exclusive Store session.
    #[must_use]
    pub fn fresh() -> Self {
        let ordinal = NEXT_V4_SESSION_IDENTITY.fetch_add(1, AtomicOrdering::Relaxed);
        let process = std::process::id();
        Self {
            digest: ContentHash::sha256(
                format!("reviewgraphen-v4-session:{process}:{ordinal}").as_bytes(),
            ),
            replay_binding: RefCell::new(None),
        }
    }

    fn matches(&self, digest: &ContentHash) -> bool {
        &self.digest == digest
    }

    fn bind_confirmed_replay(
        &self,
        run_id: &StableId,
        genesis_hash: &ContentHash,
        confirmed_tail_hash: &ContentHash,
        envelopes: &[EventEnvelope],
    ) -> Result<()> {
        let mut binding = self.replay_binding.borrow_mut();
        if let Some(previous) = binding.as_ref() {
            let extends_previous = previous.run_id == *run_id
                && previous.genesis_hash == *genesis_hash
                && previous.confirmed_tail_hash != *confirmed_tail_hash
                && envelopes
                    .iter()
                    .take(envelopes.len().saturating_sub(1))
                    .any(|envelope| envelope.event_hash() == &previous.confirmed_tail_hash);
            if !extends_previous {
                return Err(DomainError::AuthorityReplayBasisMismatch);
            }
        }
        *binding = Some(SessionReplayBindingV4 {
            run_id: run_id.clone(),
            genesis_hash: genesis_hash.clone(),
            confirmed_tail_hash: confirmed_tail_hash.clone(),
        });
        Ok(())
    }
}

#[derive(Debug)]
pub struct AuthorityReplayBasisV4 {
    schema: &'static str,
    session_identity: ContentHash,
    run_id: StableId,
    genesis_hash: ContentHash,
    confirmed_tail_hash: ContentHash,
    confirmed_event_count: u64,
    next_sequence: u64,
    policy_revision_hash: ContentHash,
    repository_id: StableId,
    repository_source_hash: ContentHash,
    snapshot_id: StableId,
    universe_id: StableId,
    inherited_m4_entries: Vec<AuthorityReplayEntryV3AtV4>,
    gluing_input_entries: Vec<GluingInputReplayEntryV4>,
    basis_digest: ContentHash,
}

#[allow(clippy::too_many_arguments)] // Every exact basis field is an independent digest input.
fn authority_replay_basis_digest_v4(
    run_id: &StableId,
    genesis_hash: &ContentHash,
    confirmed_tail_hash: &ContentHash,
    confirmed_event_count: u64,
    next_sequence: u64,
    policy_revision_hash: &ContentHash,
    repository_id: &StableId,
    repository_source_hash: &ContentHash,
    snapshot_id: &StableId,
    universe_id: &StableId,
    inherited_m4_entries: &[AuthorityReplayEntryV3AtV4],
    gluing_input_entries: &[GluingInputReplayEntryV4],
) -> Result<ContentHash> {
    let inherited_m4_entry_digests = inherited_m4_entries
        .iter()
        .map(AuthorityReplayEntryV3AtV4::digest_view)
        .collect::<Vec<_>>();
    let gluing_input_entry_digests = gluing_input_entries
        .iter()
        .map(GluingInputReplayEntryV4::digest_view)
        .collect::<Vec<_>>();
    #[derive(Serialize)]
    struct Body<'entries, 'data> {
        confirmed_event_count: u64,
        confirmed_tail_hash: &'data ContentHash,
        genesis_hash: &'data ContentHash,
        gluing_input_entries: &'entries [GluingInputReplayEntryV4Digest<'data>],
        inherited_m4_entries: &'entries [AuthorityReplayEntryV3AtV4Digest<'data>],
        next_sequence: u64,
        policy_revision_hash: &'data ContentHash,
        repository_id: &'data StableId,
        repository_source_hash: &'data ContentHash,
        run_id: &'data StableId,
        schema: &'static str,
        snapshot_id: &'data StableId,
        universe_id: &'data StableId,
    }
    Ok(ContentHash::sha256(&canonical_json(&Body {
        confirmed_event_count,
        confirmed_tail_hash,
        genesis_hash,
        gluing_input_entries: &gluing_input_entry_digests,
        inherited_m4_entries: &inherited_m4_entry_digests,
        next_sequence,
        policy_revision_hash,
        repository_id,
        repository_source_hash,
        run_id,
        schema: "reviewgraphen.authority_replay_basis.v4",
        snapshot_id,
        universe_id,
    })?))
}

impl AuthorityReplayBasisV4 {
    #[allow(clippy::too_many_arguments)] // Every exact replay coordinate is independently bound.
    fn build(
        session_identity: ContentHash,
        run_id: StableId,
        genesis_hash: ContentHash,
        confirmed_tail_hash: ContentHash,
        confirmed_event_count: u64,
        policy_revision_hash: ContentHash,
        repository_id: StableId,
        repository_source_hash: ContentHash,
        snapshot_id: StableId,
        universe_id: StableId,
        inherited_m4_entries: Vec<AuthorityReplayEntryV3AtV4>,
        gluing_input_entries: Vec<GluingInputReplayEntryV4>,
    ) -> Result<Self> {
        let next_sequence = confirmed_event_count.checked_add(1).ok_or_else(|| {
            DomainError::EventSequence("event-v4 replay sequence overflow".to_owned())
        })?;
        let schema = "reviewgraphen.authority_replay_basis.v4";
        let basis_digest = authority_replay_basis_digest_v4(
            &run_id,
            &genesis_hash,
            &confirmed_tail_hash,
            confirmed_event_count,
            next_sequence,
            &policy_revision_hash,
            &repository_id,
            &repository_source_hash,
            &snapshot_id,
            &universe_id,
            &inherited_m4_entries,
            &gluing_input_entries,
        )?;
        Ok(Self {
            schema,
            session_identity,
            run_id,
            genesis_hash,
            confirmed_tail_hash,
            confirmed_event_count,
            next_sequence,
            policy_revision_hash,
            repository_id,
            repository_source_hash,
            snapshot_id,
            universe_id,
            inherited_m4_entries,
            gluing_input_entries,
            basis_digest,
        })
    }

    #[must_use]
    pub const fn schema(&self) -> &'static str {
        self.schema
    }
    #[must_use]
    pub fn run_id(&self) -> &StableId {
        &self.run_id
    }
    #[must_use]
    pub fn genesis_hash(&self) -> &ContentHash {
        &self.genesis_hash
    }
    #[must_use]
    pub fn policy_revision_hash(&self) -> &ContentHash {
        &self.policy_revision_hash
    }
    #[must_use]
    pub fn repository_id(&self) -> &StableId {
        &self.repository_id
    }
    #[must_use]
    pub fn repository_source_hash(&self) -> &ContentHash {
        &self.repository_source_hash
    }
    #[must_use]
    pub fn snapshot_id(&self) -> &StableId {
        &self.snapshot_id
    }
    #[must_use]
    pub fn universe_id(&self) -> &StableId {
        &self.universe_id
    }
    #[must_use]
    pub fn inherited_m4_entry_count(&self) -> usize {
        self.inherited_m4_entries.len()
    }
    #[must_use]
    pub fn gluing_input_entry_count(&self) -> usize {
        self.gluing_input_entries.len()
    }
    #[must_use]
    pub fn confirmed_tail_hash(&self) -> &ContentHash {
        &self.confirmed_tail_hash
    }
    #[must_use]
    pub const fn confirmed_event_count(&self) -> u64 {
        self.confirmed_event_count
    }
    #[must_use]
    pub const fn next_sequence(&self) -> u64 {
        self.next_sequence
    }
    #[must_use]
    pub fn basis_digest(&self) -> &ContentHash {
        &self.basis_digest
    }

    #[must_use]
    pub fn session_identity_digest(&self) -> &ContentHash {
        &self.session_identity
    }

    fn validate_for_log_v4(&self, log: &EventLogV4) -> Result<()> {
        let event_count = u64::try_from(log.envelopes.len())
            .map_err(|_| DomainError::EventSequence("event-v4 event count overflow".to_owned()))?;
        if self.run_id != log.run_id
            || self.session_identity != log.session_identity
            || self.genesis_hash != log.genesis_hash
            || self.repository_id != *log.aggregate.program().repository_id()
            || self.repository_source_hash
                != *log
                    .aggregate
                    .program()
                    .repository_source()
                    .content_hash()
                    .ok_or(DomainError::AuthorityReplayBasisMismatch)?
            || self.snapshot_id != *log.aggregate.program().snapshot_id()
            || self.universe_id != *log.aggregate.universe().id()
            || self.confirmed_tail_hash != log.tail_hash
            || self.confirmed_event_count != event_count
            || self.next_sequence
                != event_count.checked_add(1).ok_or_else(|| {
                    DomainError::EventSequence("event-v4 append sequence overflow".to_owned())
                })?
            || self.basis_digest
                != authority_replay_basis_digest_v4(
                    &self.run_id,
                    &self.genesis_hash,
                    &self.confirmed_tail_hash,
                    self.confirmed_event_count,
                    self.next_sequence,
                    &self.policy_revision_hash,
                    &self.repository_id,
                    &self.repository_source_hash,
                    &self.snapshot_id,
                    &self.universe_id,
                    &self.inherited_m4_entries,
                    &self.gluing_input_entries,
                )?
        {
            return Err(DomainError::AuthorityReplayBasisMismatch);
        }
        Ok(())
    }
}

/// One-shot, position-bound admission for one exact trusted gluing-input
/// registration. It is intentionally non-cloneable and non-serializable.
///
/// ```compile_fail
/// fn require_clone<T: Clone>() {}
/// require_clone::<reviewgraphen_core::TrustedGluingInputAdmissionV4>();
/// ```
///
/// ```compile_fail
/// fn require_serialize<T: serde::Serialize>() {}
/// require_serialize::<reviewgraphen_core::TrustedGluingInputAdmissionV4>();
/// ```
#[derive(Debug)]
pub struct TrustedGluingInputAdmissionV4 {
    session_identity: ContentHash,
    basis_digest: ContentHash,
    binding: GluingInputTrustBindingV4,
    trust_binding_digest: ContentHash,
    descriptor_id: StableId,
    context_id: StableId,
    registration: ArtifactRegistrationV4,
    predecessor_event_hash: ContentHash,
    event_sequence: u64,
    start_gluing_entry_count: usize,
    envelope: EventEnvelope,
}

/// Descriptive receipt for one replay-confirmed V4 gluing-input
/// registration. It grants no authority for another append.
#[derive(Debug, Eq, PartialEq)]
pub struct ArtifactRegistrationReceiptV4 {
    session_identity: ContentHash,
    registration_id: StableId,
    descriptor_id: StableId,
    context_id: StableId,
    event_id: StableId,
    confirmed_tail_hash: ContentHash,
    expected_next_sequence: u64,
    trust_binding_digest: ContentHash,
}

impl ArtifactRegistrationReceiptV4 {
    #[must_use]
    pub fn registration_id(&self) -> &StableId {
        &self.registration_id
    }
    #[must_use]
    pub fn descriptor_id(&self) -> &StableId {
        &self.descriptor_id
    }
    #[must_use]
    pub fn context_id(&self) -> &StableId {
        &self.context_id
    }
    #[must_use]
    pub fn event_id(&self) -> &StableId {
        &self.event_id
    }
    #[must_use]
    pub fn confirmed_tail_hash(&self) -> &ContentHash {
        &self.confirmed_tail_hash
    }
    #[must_use]
    pub const fn expected_next_sequence(&self) -> u64 {
        self.expected_next_sequence
    }
    #[must_use]
    pub fn trust_binding_digest(&self) -> &ContentHash {
        &self.trust_binding_digest
    }
}

impl TrustedGluingInputAdmissionV4 {
    pub fn envelope<'a>(
        &'a self,
        log: &EventLogV4,
        basis: &AuthorityReplayBasisV4,
        session_identity: &OpaqueSessionIdentityV4,
    ) -> Result<&'a EventEnvelope> {
        basis.validate_for_log_v4(log)?;
        if !session_identity.matches(&self.session_identity)
            || self.session_identity != log.session_identity
            || self.session_identity != basis.session_identity
            || self.basis_digest != basis.basis_digest
            || self.predecessor_event_hash != log.tail_hash
            || self.event_sequence != basis.next_sequence
            || self.start_gluing_entry_count != basis.gluing_input_entries.len()
            || self.binding.registration_id != *self.registration.id()
            || self.trust_binding_digest
                != ContentHash::sha256(&canonical_gluing_binding(&self.binding)?)
        {
            return Err(DomainError::GluingInputAdmissionMismatch);
        }
        Ok(&self.envelope)
    }

    pub fn confirm_replayed(
        self,
        log: &EventLogV4,
        basis: &AuthorityReplayBasisV4,
        session_identity: &OpaqueSessionIdentityV4,
    ) -> Result<ArtifactRegistrationReceiptV4> {
        basis.validate_for_log_v4(log)?;
        let last = log.envelopes.last().ok_or_else(|| {
            DomainError::EventSequence("confirmed event-v4 prefix is empty".to_owned())
        })?;
        let expected_entries = self
            .start_gluing_entry_count
            .checked_add(1)
            .ok_or(DomainError::GluingInputAdmissionMismatch)?;
        if !session_identity.matches(&self.session_identity)
            || self.session_identity != log.session_identity
            || self.session_identity != basis.session_identity
            || self.event_sequence != last.sequence()
            || self.event_sequence != basis.confirmed_event_count
            || self.predecessor_event_hash != *last.previous_event_hash()
            || basis.confirmed_tail_hash != *self.envelope.event_hash()
            || basis.next_sequence != self.event_sequence.saturating_add(1)
            || basis.gluing_input_entries.len() != expected_entries
            || log.m5_bundle.is_some()
            || log.v4_registrations.get(self.registration.id()) != Some(&self.registration)
            || log
                .v4_gluing_descriptors
                .get(&self.context_id)
                .is_none_or(|descriptor| descriptor.id() != &self.descriptor_id)
            || last.canonical_bytes()? != self.envelope.canonical_bytes()?
            || self.trust_binding_digest
                != ContentHash::sha256(&canonical_gluing_binding(&self.binding)?)
        {
            return Err(DomainError::GluingInputAdmissionMismatch);
        }
        Ok(ArtifactRegistrationReceiptV4 {
            session_identity: self.session_identity,
            registration_id: self.registration.id().clone(),
            descriptor_id: self.descriptor_id,
            context_id: self.context_id,
            event_id: self.envelope.id().clone(),
            confirmed_tail_hash: self.envelope.event_hash().clone(),
            expected_next_sequence: basis.next_sequence,
            trust_binding_digest: self.trust_binding_digest,
        })
    }
}

/// One sealed, authority-free atomic M5 bundle event. The value can only be
/// confirmed once and is never a constructor for its owned topology records.
///
/// ```compile_fail
/// fn require_clone<T: Clone>() {}
/// require_clone::<reviewgraphen_core::ValidatedGluingBundleV4>();
/// ```
///
/// ```compile_fail
/// fn require_serialize<T: serde::Serialize>() {}
/// require_serialize::<reviewgraphen_core::ValidatedGluingBundleV4>();
/// ```
#[derive(Debug)]
pub struct ValidatedGluingBundleV4 {
    session_identity: ContentHash,
    basis_digest: ContentHash,
    start_gluing_entry_count: usize,
    bundle: crate::GluingBundleV4,
    predecessor_event_hash: ContentHash,
    event_sequence: u64,
    envelope: EventEnvelope,
}

#[derive(Debug, Eq, PartialEq)]
pub struct GluingBundleReceiptV4 {
    session_identity: ContentHash,
    event_id: StableId,
    cover_id: StableId,
    attempt_id: StableId,
    result: crate::GluingResultV4,
    confirmed_tail_hash: ContentHash,
    expected_next_sequence: u64,
}

impl GluingBundleReceiptV4 {
    #[must_use]
    pub fn event_id(&self) -> &StableId {
        &self.event_id
    }
    #[must_use]
    pub fn cover_id(&self) -> &StableId {
        &self.cover_id
    }
    #[must_use]
    pub fn attempt_id(&self) -> &StableId {
        &self.attempt_id
    }
    #[must_use]
    pub const fn result(&self) -> crate::GluingResultV4 {
        self.result
    }
    #[must_use]
    pub fn confirmed_tail_hash(&self) -> &ContentHash {
        &self.confirmed_tail_hash
    }
    #[must_use]
    pub const fn expected_next_sequence(&self) -> u64 {
        self.expected_next_sequence
    }
}

impl ValidatedGluingBundleV4 {
    pub fn envelope<'a>(
        &'a self,
        log: &EventLogV4,
        basis: &AuthorityReplayBasisV4,
        session_identity: &OpaqueSessionIdentityV4,
    ) -> Result<&'a EventEnvelope> {
        basis.validate_for_log_v4(log)?;
        if !session_identity.matches(&self.session_identity)
            || self.session_identity != log.session_identity
            || self.session_identity != basis.session_identity
            || self.basis_digest != basis.basis_digest
            || self.predecessor_event_hash != log.tail_hash
            || self.event_sequence != basis.next_sequence
            || self.start_gluing_entry_count != basis.gluing_input_entries.len()
            || log.m5_bundle.is_some()
        {
            return Err(DomainError::GluingBundleMismatch);
        }
        Ok(&self.envelope)
    }

    pub fn confirm_replayed(
        self,
        log: &EventLogV4,
        basis: &AuthorityReplayBasisV4,
        session_identity: &OpaqueSessionIdentityV4,
    ) -> Result<GluingBundleReceiptV4> {
        basis.validate_for_log_v4(log)?;
        let last = log.envelopes.last().ok_or_else(|| {
            DomainError::EventSequence("confirmed event-v4 prefix is empty".to_owned())
        })?;
        if !session_identity.matches(&self.session_identity)
            || self.session_identity != log.session_identity
            || self.session_identity != basis.session_identity
            || self.event_sequence != last.sequence()
            || self.event_sequence != basis.confirmed_event_count
            || basis.next_sequence != self.event_sequence.saturating_add(1)
            || basis.gluing_input_entries.len() != self.start_gluing_entry_count
            || last.canonical_bytes()? != self.envelope.canonical_bytes()?
            || log.m5_bundle.as_ref() != Some(&self.bundle)
        {
            return Err(DomainError::GluingBundleMismatch);
        }
        Ok(GluingBundleReceiptV4 {
            session_identity: self.session_identity,
            event_id: self.envelope.id().clone(),
            cover_id: self.bundle.cover().id().clone(),
            attempt_id: self.bundle.attempt().id().clone(),
            result: self.bundle.attempt().result(),
            confirmed_tail_hash: self.envelope.event_hash().clone(),
            expected_next_sequence: basis.next_sequence,
        })
    }
}

